      cube: { action: { type: "dialog", dialog: { title: "Le Cube de Porc", icon: "info", body: "Le Cube de Porc ne s'exécute pas. Il se visite, à pied, par ses quatre côtés accessibles.\n\nOn touche la paroi froide, puis on prend une bière au comptoir de sortie. On n'en coupe pas de tranche.", buttons: [{ label: "J'irai" }] } } },
