      bonjour: { action: { type: "dialog", dialog: { title: "Bonjour", icon: "info", body: "Bonjour.\n\nLe poste vous a entendu. Il ne répond qu'aux commandes, mais il a été touché.", buttons: [{ label: "Bonjour" }] } } },
