  installeurs: [
    {
      id: "jambonjon",
      programme: "jambonjon",
      nom: "Jambonjon",
      version: "1.0",
      editeur: "Grenier à Partagiciels (Kévin et un ami)",
      accueil: "Cet assistant va installer Jambonjon 1.0 sur votre poste.\n\nIl est conseillé de fermer tous les autres programmes avant de continuer. Il est également conseillé de manger quelque chose : l'installation est rapide, mais le jeu ne l'est pas.\n\nCliquez sur Suivant pour continuer.",
      licence: "CONTRAT DE LICENCE DU CITOYEN-JOUEUR\n\n1. Le présent logiciel vous est concédé, et non vendu, et non donné, et non prêté. Il est concédé.\n\n2. Vous pouvez installer Jambonjon sur un poste. Sur deux postes, c'est de la convivialité ; sur trois, de la contrebande.\n\n3. Les jambons du jeu sont fictifs. Toute tentative de les manger hors du jeu engage votre seule responsabilité, et votre écran.\n\n4. Les inspecteurs des fraudes salées représentés dans le jeu ne sont pas de vrais inspecteurs. Les vrais inspecteurs ont été consultés. Ils n'ont rien dit, ce qui est pire.\n\n5. L'éditeur ne saurait être tenu responsable des pertes de sommeil, de PV, de jambons ou de dignité.\n\n6. En cliquant sur « J'accepte », vous reconnaissez avoir lu le présent contrat. Personne ne vous croira, mais c'est écrit.",
      dossier: "Programmes/Jambonjon",
      options: [
        { id: "pignet-plus", label: "Installer aussi la barre d'outils PigNet Plus (recommandé)", coche: true },
        { id: "scores", label: "Transmettre mes scores au Ministère des Loisirs", coche: true, imposee: "Obligatoire depuis la loi sur les loisirs déclarés." },
        { id: "demarrage", label: "Lancer Jambonjon au démarrage de PorkOS", coche: false },
      ],
      composants: [
        { id: "jeu", label: "Jambonjon (programme principal)", description: "Le jeu, ses caves et ses rats.", taille: 2410, obligatoire: true, fichiers: [{ type: "texte", name: "LISEZMOI.TXT", date: "01/04/2003", content: "JAMBONJON 1.0\n=============\n\nCOMMANDES\n  Z / S ........ avancer / reculer\n  Q / D ........ pas de côté à gauche / à droite\n  A / E ........ tourner d'un quart de tour\n  Espace ....... frapper, ou descendre l'escalier\n  J ............ manger un jambon (PV et faim)\n  B ............ boire une bière (mousse, et un peu d'ivresse)\n  R ............ rot d'État (30 de mousse, trois cases devant)\n  I ............ sac et équipement\n  C ............ carte\n\nCONSEILS\n- La faim baisse en marchant. Un citoyen affamé perd des PV.\n- La bière rend fort mais maladroit : on titube.\n- Les monstres ont un niveau. Un rat de niveau 5 reste un rat, mais un rat qui a lu.\n- Les objets « d'État » sont les meilleurs. Ils sont aussi les plus rares, comme l'État.\n\nMerci d'avoir téléchargé Jambonjon. Si vous trouvez un bogue, gardez-le, il est à vous." }] },
        { id: "manuel", label: "Manuel du citoyen-explorateur", description: "Bestiaire illustré, sans illustrations.", taille: 184, fichiers: [{ type: "texte", name: "MANUEL.TXT", date: "01/04/2003", content: "MANUEL DU CITOYEN-EXPLORATEUR\n\nLes caves d'affinage s'étendent sous chaque ville de la République. Personne ne sait qui les a creusées. Tout le monde sait qui les affine.\n\nBESTIAIRE\n- Rat de cave : petit, nombreux, syndiqué.\n- Moisissure noble : lente. Très lente. Mais elle a le temps.\n- Gobelin chapardeur : vole, frappe, revend.\n- Saucisson animé : on ne sait pas qui l'a animé. On ne veut pas savoir.\n- Inspecteur des fraudes salées : verbalise à vue.\n- Tonneau mimique : n'ouvrez pas un tonneau qui vous regarde.\n- Spectre de l'affinage : ce qui reste d'un jambon oublié.\n- Le Grand Affineur : au fond. Toujours au fond.\n\nRARETÉS\nCommun, de garde, grand cru, d'État. Plus c'est rare, plus c'est fort." }] },
        { id: "textures", label: "Textures haute définition", description: "Ajoute quatre couleurs. Vous ne les verrez pas, mais elles sont là.", taille: 512, fichiers: [] },
      ],
      copie: ["JBJ.EXE", "CAVES.DAT", "MONSTRES.DAT", "JAMBON.BMP", "CHOPE.BMP", "BRUME.DLL", "AFFINAGE.DLL", "ROT.WAV", "COMMISSION.INI", "PIGNETPLUS.DLL", "SCORES_MINISTERE.DLL", "LISEZMOI.TXT"],
      raccourci: "Jambonjon",
      fin: "Jambonjon 1.0 a été installé sur votre poste.\n\nLa barre d'outils PigNet Plus a également été installée si vous l'avez laissée cochée. Elle ne fait rien, mais elle le fait en permanence.",
      desinstallation: { question: "Voulez-vous vraiment supprimer Jambonjon et tous ses composants ? Les caves resteront où elles sont.", fin: "Jambonjon a été supprimé de votre poste. Les rats, eux, sont restés." },
    },
  ],

